<script setup lang="ts">
import {ref,watch,onUnmounted,nextTick} from 'vue';
import {Archive,RefreshCw,Upload,RotateCcw,ShieldCheck,X,LoaderCircle} from 'lucide-vue-next';
import {invoke} from '../bridge';
import {trapModalFocus} from '../modalFocus';
import {useDesktop} from '../useDesktop';
import type {Instance,ModulePreview,ModuleRecord} from '../../types';
const props=defineProps<{instance:Instance}>();const d=useDesktop();const records=ref<ModuleRecord[]>([]),busy=ref(false),loading=ref(false),error=ref(''),message=ref(''),preview=ref<ModulePreview|null>(null),rollback=ref<ModuleRecord|null>(null),ticket=ref(''),trusted=ref(false),granted=ref(false),dialog=ref<HTMLElement|null>(null);let generation=0,selectionEpoch=0,disposed=false,release:(()=>void)|undefined;
const codes:Record<string,string>={host_incompatible:'此酒馆实际安装的本体版本不支持该模块。',dependencies_unavailable:'缺少兼容依赖或存在依赖循环，请先处理依赖。',gm_implementation_missing:'后端未实现声明的主持接口，原版保留。',pinned_rooms_require_original:'有房间锁定此精确模块版本，原锁保留。请在独立实例制作新的明确版本。',builtin_managed_by_host:'内置模块随本体版本管理，不能用社区包覆盖。',python_trust_required:'Python 代码与迁移需要明确授信。',capability_grant_required:'高风险界面能力需要明确批准。',version_not_newer:'升级包版本必须更高；回退请选择保留的快照。',archive_changed:'ZIP 与预览 SHA256 不匹配，请重新选择。',source_changed:'当前模块已改变，请刷新后重新预览。',invalid_trust_record:'授权记录无法确认，原文件保留。',checkpoint_changed:'旧代码快照散列不匹配，停止并保留资料。',recovery_blocked:'恢复资料需要检查，保持停止并保留数据。',host_update_in_progress:'本体更新尚未恢复完成，请先处理版本任务。',module_operation_failed:'模块操作未通过，原恢复资料保留；检查清单、迁移实现与环境。'};
async function load(){if(loading.value)return;loading.value=true;const token=++generation;try{const value=await invoke('moduleHistory',{instanceId:props.instance.id});if(token!==generation||disposed)return;if(!value.result?.ok)throw new Error(codes[value.result?.code]||'模块记录无法读取，原文件保留');records.value=value.result.records;error.value='';}catch(e:any){if(token===generation)error.value=e.message;}finally{if(token===generation)loading.value=false;}}
async function operation(action:(instanceId:string,valid:()=>boolean)=>Promise<void>){if(busy.value)return;const epoch=selectionEpoch,instanceId=props.instance.id,valid=()=>!disposed&&selectionEpoch===epoch;busy.value=true;error.value='';message.value='';try{await action(instanceId,valid);}catch(e:any){if(valid())error.value=e.message;}finally{if(valid())busy.value=false;}}
async function focus(){await nextTick();if(dialog.value)release=trapModalFocus(dialog.value,()=>{if(!busy.value)close();});}
function close(){release?.();release=undefined;preview.value=null;rollback.value=null;ticket.value='';trusted.value=false;granted.value=false;}
function choose(){void operation(async(instanceId,valid)=>{const value=await invoke('modulePreview',{instanceId});if(!valid()||value.cancelled)return;if(!value.result?.ok)throw new Error(codes[value.result?.code]||'模块包需要检查');preview.value=value.result;ticket.value=value.ticket;trusted.value=false;granted.value=false;await focus();});}
function review(record:ModuleRecord){if(preview.value||rollback.value)return;rollback.value=record;trusted.value=false;granted.value=false;void focus();}
function apply(){void operation(async(instanceId,valid)=>{const value=preview.value?await invoke('moduleUpgrade',{instanceId,ticket:ticket.value,trustBackend:trusted.value,grantCapabilities:granted.value}):await invoke('moduleRollback',{instanceId,checkpointId:rollback.value!.id,trustBackend:trusted.value,grantCapabilities:granted.value});if(!valid()||value.cancelled)return;close();message.value='备份与模块事务已开始，请在任务中心确认结果。完成后保持停止等待审阅。';await d.refresh();});}
watch(()=>props.instance.id,()=>{selectionEpoch++;close();records.value=[];error.value='';message.value='';busy.value=false;loading.value=false;void load();},{immediate:true});watch(()=>props.instance.task,(current,old)=>{if(!current&&old&&['plugin-upgrade','plugin-rollback'].includes(old.kind))void load();});onUnmounted(()=>{disposed=true;generation++;selectionEpoch++;release?.();});
</script>
<template><section class="panel module-versions"><div class="panel-title"><h3><Archive :size="18"/>模块版本与回退</h3><div class="row"><button class="text-button" :disabled="busy||loading||instance.status==='busy'" @click="load"><RefreshCw :size="15"/>刷新模块版本</button><button class="secondary" :disabled="busy||loading||!instance.commit||instance.status==='busy'" @click="choose"><Upload :size="16"/>预览升级 ZIP</button></div></div><p class="help-text">社区模块升级需停服、完整备份与副本迁移预检；保留旧代码和模块数据，旧房间的精确内容 / 规则 / 模块锁不自动修改。内置模块通过本体版本切换管理。</p><p v-if="error" class="warning" role="alert">{{error}}</p><p v-if="message" class="help-text" role="status">{{message}}</p><p v-if="busy" class="help-text"><LoaderCircle :size="15" class="spin"/>正在处理模块版本…</p><p v-if="!records.length" class="help-text">还没有模块版本事务。首次安装使用本页的原生 ZIP 安装入口。</p><article v-for="record in records" :key="record.id" class="module-record"><div><b>{{record.plugin_id}} · {{record.old_version}} → {{record.new_version}}</b><small>{{record.action==='rollback'?'模块回退':'模块升级'}} · {{record.created_at}} · {{record.state==='committed'?'已完成':record.state==='recovered'?'原版已恢复':'需检查恢复'}}</small><p v-if="record.pinned_rooms" class="warning">{{record.pinned_rooms}} 个房间要求其他精确版本，不能直接回退。</p></div><button class="text-button" :disabled="busy||loading||!record.can_rollback||instance.status==='running'||instance.status==='busy'" @click="review(record)"><RotateCcw :size="15"/>审阅并回退</button></article></section>
<Teleport to="body"><div v-if="preview||rollback" class="overlay"><section ref="dialog" class="dialog" role="dialog" aria-modal="true" aria-label="模块版本影响预览"><button class="dialog-close" aria-label="关闭模块预览" :disabled="busy" @click="close"><X :size="20"/></button><span class="eyebrow">EXPLICIT MODULE VERSION</span><h2>{{preview?'升级模块':'回退模块与模块数据'}}</h2><p>{{(preview||rollback)!.plugin_id}} · {{preview?preview.old_version+' → '+preview.new_version:rollback!.new_version+' → '+rollback!.old_version}}</p><p class="help-text">先备份当前完整数据，迁移在数据库副本预检。旧模块代码与数据保留；事务中断先恢复再允许启动。操作后保持停止等待审阅。</p><p v-if="rollback" class="help-text">仅此模块的数据恢复到切换前，当前剧情、规则、房间内容锁、成员、会话、角色分配与邀请权限保留。较新模块数据另有新备份，新建房间没有旧模块数据的将重新初始化此模块。</p><div v-if="preview" class="help-text"><p>{{preview.name}} · {{preview.authors?.join('、')||'未声明作者'}} · {{preview.license||'未声明许可'}}</p><p>最低本体 {{preview.minimum_host}}；依赖 {{preview.requires?.join('、')||'无'}}；声明能力 {{preview.capabilities?.join('、')||'无'}}</p><p v-if="preview.dependency_issues?.length" class="warning">依赖缺失、不兼容或循环：{{preview.dependency_issues.join('、')}}。先处理依赖。</p></div><p v-if="preview?.pinned_rooms" class="warning">{{preview.pinned_rooms}} 个房间锁定原版本，当前升级被阻止；不会替换旧房间 pins。</p><p v-if="preview&&!preview.can_upgrade&&!preview.pinned_rooms&&!preview.dependency_issues?.length" class="warning">包版本并不高于当前版本，请选择新的发行版或使用保留快照回退。</p><details><summary>审阅精确散列</summary><code class="content-hash">{{preview?'ZIP SHA256 · '+preview.archive_sha256:'旧模块 SHA256 · '+rollback!.old_hash}}</code><code v-if="preview" class="content-hash">模块散列 · {{preview.new_hash}}</code></details><label v-if="(preview||rollback)!.backend" class="checkbox"><input v-model="trusted" type="checkbox" :disabled="busy"/>已审阅源码，明确信任完整 Python 服务器代码并执行迁移</label><label v-else-if="(preview||rollback)!.capability_grant" class="checkbox"><input v-model="granted" type="checkbox" :disabled="busy"/>已审阅并批准此版本声明的高风险界面能力</label><p class="help-text"><ShieldCheck :size="14"/>散列与备份不授予代码信任；已授信代码的文件、网络和线程副作用不能通过回退撤销。</p><p v-if="busy" class="help-text" role="status">正在重新检查版本并提交任务，请等待结果…</p><p v-else-if="instance.status==='running'||instance.status==='busy'" class="warning">先停止酒馆，并等待当前任务结束，再确认变更。</p><p v-if="error" class="warning" role="alert">{{error}}</p><div class="row"><button class="secondary" :disabled="busy" @click="close">取消</button><button class="primary" :disabled="busy||loading||instance.status==='running'||instance.status==='busy'||!!preview&&!preview.can_upgrade||(preview||rollback)!.backend&&!trusted||!(preview||rollback)!.backend&&(preview||rollback)!.capability_grant&&!granted" @click="apply">继续确认备份与影响</button></div></section></div></Teleport></template>
